const Sevabarathi = () => {
  useEffect(() => {
    // Animation for content to fade in on page load
    const content = document.getElementById('women-content');
    if (content) {
      setTimeout(() => {
        content.classList.remove('opacity-0', 'translate-y-10');
        content.classList.add('opacity-100', 'translate-y-0');
      }, 100);
    }
  }, []);
  
  const { language } = useLanguage();

  return (
    <div className="min-h-screen flex flex-col">
      {/* Navbar would be here */}
      
      {/* Hero Section */}
      <div className="relative bg-pink-800 text-white py-20">
        <div className="container mx-auto px-4">
          <div id="women-content" className="max-w-4xl mx-auto transition-all duration-700 ease-out opacity-0 translate-y-10">
            <h1 className="text-3xl md:text-5xl font-bold mb-4 text-center text-pink-200">
              {content[language].header}
            </h1>
            <p className="text-xl text-center mb-8">
              {content[language].subtitle}
            </p>
          </div>
        </div>
      </div>
      
      {/* Main Content */}
      <main className="container mx-auto px-4 py-12 flex-grow">
        <div className="max-w-4xl mx-auto">
          {/* Back button */}
          <div className="mb-8">
            <Link href="/services" className="inline-flex items-center text-pink-600 hover:text-pink-800 transition-colors">
              <ArrowLeft className="mr-2 h-4 w-4" />
              {content[language].backButton}
            </Link>
          </div>
          
          <div className="bg-white rounded-xl shadow-lg p-6 md:p-8">
            <p className="text-lg text-gray-700 leading-relaxed mb-8">
              {content[language].introduction}
            </p>
            
            {content[language].sections.map((section, index) => (
              <div key={index} className="mb-12">
                <h2 className="text-2xl font-bold text-pink-800 mb-4">
                  {section.title}
                </h2>
                <p className="text-gray-700 leading-relaxed mb-6">
                  {section.content}
                </p>
                {section.hasImage && (
                  <div className="p-2 rounded-lg mb-6">
                    <div className="h-80 rounded-lg flex items-center justify-center bg-gray-200 overflow-hidden">
                      <Image 
                        src={`/images/seva-${index + 1}.jpg`} 
                        alt={section.imageAlt}
                        width={300} 
                        height={300}
                        className="rounded-lg object-cover w-full h-full"
                      />
                    </div>
                  </div>
                )}
              </div>
            ))}
            
            {/* Program Highlights */}
            <div className="bg-pink-50 rounded-lg p-6 mb-8">
              <h3 className="text-xl font-bold text-pink-800 mb-4">
                {content[language].highlights.title}
              </h3>
              <div className="space-y-4">
                {content[language].highlights.programs.map((program, index) => (
                  <div key={index} className="bg-white p-4 rounded-lg shadow">
                    <h4 className="font-bold text-pink-700 mb-2">{program.name}</h4>
                    <p className="text-gray-700 mb-2">
                      {program.description}
                    </p>
                    <div className="flex items-center text-sm text-pink-600">
                      <Star className="h-4 w-4 mr-2" />
                      <span>{program.achievement}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
            
            <div className="border-t border-gray-200 pt-8 mt-8">
              <p className="text-lg text-gray-700 leading-relaxed italic">
                {content[language].conclusion}
              </p>
            </div>
          </div>
        </div>
      </main>
      
      {/* Footer would be here */}
    </div>
  );
};

export default Sevabarathi;